<?php /** @var array $c @var array $dist @var array $attachments @var array $departments @var int $myDept */
$mine = null; foreach ($dist as $d) { if ((int)$d['department_id'] === $myDept) { $mine = $d; } }
$steps = ['draft', 'distributed', 'closed']; $cur = array_search($c['status'], $steps, true); ?>
<div class="page-head"><div><h1><?= icon('file') ?> <?= e($c['code']) ?> — <?= e($c['title']) ?></h1><p class="sub"><?= e($c['issuer']) ?><?= $c['reference_no'] ? ' · ' . e($c['reference_no']) : '' ?></p></div>
  <div class="actions"><a class="btn secondary" href="<?= e(url('circulars')) ?>"><?= e(t('common.back')) ?></a><?php if (can('kb.manage')): ?><form method="post" class="inline" action="<?= e(url('circulars/' . $c['id'] . '/to-library')) ?>"><?= csrf_field() ?><button class="btn secondary" type="submit"><?= icon('book') ?> <?= e(t('ai.add_circular')) ?></button></form><?php endif; ?><?php if (can('circular.manage') && $c['status'] === 'draft'): ?><a class="btn" href="<?= e(url('circulars/' . $c['id'] . '/edit')) ?>"><?= e(t('common.edit')) ?></a><?php endif; ?></div></div>
<ol class="stepper"><?php foreach ($steps as $i => $s): ?><li class="<?= $i < $cur ? 'done' : ($i === $cur ? 'current' : '') ?>"<?= $i === $cur ? ' aria-current="step"' : '' ?>><?= e(t('enum.cstatus.' . $s)) ?></li><?php endforeach; ?></ol>
<section class="card"><dl class="details"><dt><?= e(t('cir.issued_on')) ?></dt><dd><?= e(fdate($c['issued_on'])) ?></dd><dt><?= e(t('cir.received_on')) ?></dt><dd><?= e(fdate($c['received_on'])) ?></dd><dt><?= e(t('cir.due_date')) ?></dt><dd><?= e(fdate($c['due_date']) ?: '—') ?></dd>
<dt><?= e(t('cir.obligation')) ?></dt><dd><?= $c['obligation_id'] ? '<a href="' . e(url('compliance/' . $c['obligation_id'])) . '">' . e($c['obl_code'] . ' — ' . $c['obl_title']) . '</a>' : '—' ?></dd>
<dt><?= e(t('cir.summary')) ?></dt><dd class="pre"><?= e($c['summary']) ?></dd><dt><?= e(t('cir.required_action')) ?></dt><dd class="pre"><?= e($c['required_action'] ?? '—') ?></dd></dl></section>
<?php if ($c['status'] === 'draft' && can('circular.manage')): ?><section class="card"><h2><?= e(t('cir.distribute')) ?></h2><p class="muted"><?= e(t('cir.distribute_hint')) ?></p>
<form method="post" action="<?= e(url('circulars/' . $c['id'] . '/distribute')) ?>"><?= csrf_field() ?><div class="form-grid"><?php foreach ($departments as $d): ?><label class="check"><input type="checkbox" name="departments[]" value="<?= (int)$d['id'] ?>"> <?= e(lname($d)) ?></label><?php endforeach; ?></div>
<div class="actions" style="margin-top:12px"><button class="btn gold" type="submit"><?= e(t('cir.distribute_btn')) ?></button></div></form></section><?php endif; ?>
<?php if ($dist): ?><section class="card"><h2><?= e(t('cir.distribution')) ?></h2><div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('bia.department')) ?></th><th><?= e(t('cir.status')) ?></th><th><?= e(t('cir.acknowledged_by')) ?></th><th><?= e(t('cir.action_taken')) ?></th></tr></thead><tbody>
<?php foreach ($dist as $d): ?><tr><td><?= e(lname($d, 'dept')) ?></td><td><span class="badge <?= $d['status'] === 'acknowledged' ? 'ok' : 'warn' ?>"><?= e(t('enum.dstat.' . $d['status'])) ?></span></td><td><?= e($d['ack_name'] ?? '—') ?> <?= $d['acknowledged_at'] ? '<span class="muted">' . e(fdatetime($d['acknowledged_at'])) . '</span>' : '' ?></td><td class="pre"><?= e($d['action_taken'] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php if ($mine && $mine['status'] === 'pending' && $c['status'] === 'distributed' && can('circular.ack')): ?><section class="card" id="ack"><h2><?= e(t('cir.ack_title')) ?></h2>
<form method="post" action="<?= e(url('circulars/' . $c['id'] . '/acknowledge')) ?>" novalidate><?= csrf_field() ?>
<?= ff('textarea', 'action_taken', 'cir.action_taken', '', ['required' => $c['required_action'] !== null, 'hint' => t('cir.action_taken_hint'), 'extra' => ' rows="4"']) ?>
<button class="btn" type="submit"><?= e(t('cir.ack_btn')) ?></button></form></section><?php endif; ?>
<section class="card" id="attachments"><h2><?= e(t('upload.title')) ?></h2>
<?php if (!$attachments): ?><p class="muted"><?= e(t('upload.empty')) ?></p><?php else: ?><ul><?php foreach ($attachments as $a): ?><li><a href="<?= e(url('attachments/' . $a['id'])) ?>"><?= e($a['original_name']) ?></a><?php if (can('circular.manage')): ?> <form method="post" class="inline" action="<?= e(url('attachments/' . $a['id'] . '/delete')) ?>" data-confirm="<?= e(t('upload.confirm_delete')) ?>"><?= csrf_field() ?><button class="btn small danger" type="submit"><?= e(t('common.delete')) ?></button></form><?php endif; ?></li><?php endforeach; ?></ul><?php endif; ?>
<?php if (can('circular.manage')): ?><form method="post" enctype="multipart/form-data" action="<?= e(url('circulars/' . $c['id'] . '/attachments')) ?>"><?= csrf_field() ?><div class="field"><label for="file"><?= e(t('upload.choose')) ?></label><input type="file" id="file" name="file" required></div><button class="btn secondary" type="submit"><?= e(t('upload.submit')) ?></button></form><?php endif; ?></section>
